PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "app_users" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "email" varchar NOT NULL, "name" varchar, "password_hash" varchar, "remember_token" varchar, "email_verified_at" timestamp_with_timezone_text, "locked_at" timestamp_with_timezone_text, "auth_epoch" bigint NOT NULL, "created_at" timestamp_with_timezone_text, "updated_at" timestamp_with_timezone_text );
INSERT INTO app_users VALUES(6100,'seaorm11@example.test','SeaORM 1.1 fixture','fixture-hash',NULL,'2026-08-23T12:00:00+00:00',NULL,0,'2026-08-23T12:00:00+00:00','2026-08-23T12:00:00+00:00');
CREATE TABLE IF NOT EXISTS "auth_sessions" ( "id" varchar NOT NULL PRIMARY KEY, "user_id" bigint NOT NULL, "auth_epoch" bigint NOT NULL, "token_digest" varchar NOT NULL, "token_hash" varchar, "user_agent" varchar, "ip_address" varchar, "expires_at" timestamp_with_timezone_text NOT NULL, "revoked_at" timestamp_with_timezone_text );
INSERT INTO auth_sessions VALUES('seaorm11-session',6100,0,'3abda255ff0ff2f5f526a8898ca27e01554f300be8641bbf15df18415e8ae9b1','3abda255ff0ff2f5f526a8898ca27e01554f300be8641bbf15df18415e8ae9b1','fixture-agent','192.0.2.61','2036-08-23T12:00:00+00:00',NULL);
CREATE TABLE IF NOT EXISTS "auth_methods" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL, "credential_id" varchar, "public_key" varchar, "created_at" timestamp_with_timezone_text );
CREATE TABLE IF NOT EXISTS "auth_linked_accounts" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL, "provider" varchar NOT NULL, "provider_account_id" varchar NOT NULL, "created_at" timestamp_with_timezone_text, "updated_at" timestamp_with_timezone_text );
CREATE TABLE IF NOT EXISTS "auth_tokens" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint, "purpose" varchar NOT NULL, "digest" varchar NOT NULL, "expires_at" timestamp_with_timezone_text NOT NULL, "used_at" timestamp_with_timezone_text, "created_at" timestamp_with_timezone_text, "updated_at" timestamp_with_timezone_text );
INSERT INTO auth_tokens VALUES(6102,6100,'password-reset','102ce6cc88841311d1339a55bdea7604675bc6a864be3ad7ca4f955a3fad83c0','2036-08-23T12:00:00+00:00',NULL,'2026-08-23T12:00:00+00:00','2026-08-23T12:00:00+00:00');
CREATE TABLE IF NOT EXISTS "auth_ceremonies" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "kind" varchar NOT NULL, "selector" varchar NOT NULL, "payload" varbinary_blob NOT NULL, "state" varchar NOT NULL, "expires_at" timestamp_with_timezone_text NOT NULL, "used_at" timestamp_with_timezone_text );
CREATE TABLE IF NOT EXISTS "auth_lockouts" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "identity" varchar NOT NULL, "attempted_at" timestamp_with_timezone_text NOT NULL, "ip_address" varchar, "migration_source_id" varchar, "locked_at" timestamp_with_timezone_text, "reason" varchar );
CREATE TABLE IF NOT EXISTS "auth_remember_tokens" ( "id" varchar NOT NULL PRIMARY KEY, "selector" varchar NOT NULL, "user_id" varchar NOT NULL, "auth_epoch" bigint NOT NULL, "verifier_hash" varchar NOT NULL, "expires_at" timestamp_with_timezone_text NOT NULL );
CREATE TABLE IF NOT EXISTS "auth_two_factor" ( "user_id" varchar NOT NULL PRIMARY KEY, "secret" varbinary_blob NOT NULL, "recovery_codes" varbinary_blob, "enrollment_auth_epoch" bigint NOT NULL, "enrollment_session_id" varchar, "enrollment_expires_at" timestamp_with_timezone_text, "rotation_pending" boolean NOT NULL, "confirmed_at" timestamp_with_timezone_text, "last_used_timestep" bigint, "created_at" timestamp_with_timezone_text, "updated_at" timestamp_with_timezone_text );
CREATE TABLE IF NOT EXISTS "auth_lifecycle_deliveries" ( "mutation_id" varchar NOT NULL PRIMARY KEY, "lease_id" varchar, "lease_until" timestamp_with_timezone_text, "delivered_at" timestamp_with_timezone_text );
CREATE TABLE IF NOT EXISTS "auth_migration_runs" ( "plan_id" varchar NOT NULL PRIMARY KEY, "imports_committed" boolean NOT NULL, "completed_at" timestamp_with_timezone_text );
CREATE TABLE IF NOT EXISTS "auth_migration_identities" ( "id" varchar NOT NULL PRIMARY KEY, "plan_id" varchar NOT NULL, "source_user_id" varchar NOT NULL, "app_user_id" bigint NOT NULL );
CREATE TABLE IF NOT EXISTS "magnetar_migration_state" ( "key" varchar NOT NULL PRIMARY KEY, "value" varchar NOT NULL );
INSERT INTO magnetar_migration_state VALUES('schema_version','1');
CREATE TABLE IF NOT EXISTS "auth_provider_tokens" ( "id" varchar NOT NULL PRIMARY KEY, "provider" varchar NOT NULL, "access_ciphertext" varbinary_blob NOT NULL, "refresh_ciphertext" varbinary_blob, "raw_payload_ciphertext" varbinary_blob NOT NULL, "token_type" varchar NOT NULL, "scopes" varchar NOT NULL, "access_expires_at" timestamp_with_timezone_text, "generation" bigint NOT NULL, "claim_id" varchar, "claim_deadline" timestamp_with_timezone_text, "revoked_at" timestamp_with_timezone_text, "revoked_reused" boolean, "created_at" timestamp_with_timezone_text NOT NULL );
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
INSERT INTO sqlite_sequence VALUES('app_users',6100);
INSERT INTO sqlite_sequence VALUES('auth_tokens',6102);
CREATE UNIQUE INDEX "auth_linked_accounts_provider_subject" ON "auth_linked_accounts" ("provider", "provider_account_id");
CREATE UNIQUE INDEX "auth_lockouts_migration_source" ON "auth_lockouts" ("migration_source_id");
PRAGMA writable_schema=OFF;
COMMIT;
